diff --git "a/server/lib/stripe.js" "b/server/lib/stripe.js"
--- "a/server/lib/stripe.js"
+++ "b/server/lib/stripe.js"
@@ -1,39 +1,39 @@
-import Stripe from 'stripe';
-import { config } from '../config.js';
-import logger from './logger.js';
-
-let stripe = null;
-
-export function getStripe() {
-    if (!stripe && config.stripeSecretKey) {
-        try {
-            stripe = new Stripe(config.stripeSecretKey, {
-                apiVersion: '2024-12-18.acacia',
-            });
-        } catch (err) {
-            logger.warn({ err }, 'Failed to initialize Stripe client');
-        }
-    }
-    if (!stripe && config.stripeSecretKey) {
-        logger.warn('getStripe() returned null but STRIPE_SECRET_KEY is configured');
-    }
-    return stripe;
-}
-
-/**
- * Billing is enabled only when BOTH halves of the Stripe pair are present.
- *
- * The secret key alone is enough to open a checkout and charge a card, but
- * without the webhook signing secret every event Stripe sends back is refused
- * (stripe-webhooks.js answers 503), so no licence is issued and no e-mail is
- * sent: the customer pays and receives nothing. In production the boot audit
- * already refuses to start in that state (startup-secrets-check.js), which is
- * why this never reached the live instance — but a self-hosted or staging
- * instance running outside production had no such guard, and this module
- * disagreed with the shell, which has always required both before advertising
- * a priced plan (index.js). One predicate, one answer: a half-configured
- * install advertises Free and answers 503 on checkout, which is the truth.
- */
-export function isStripeEnabled() {
-    return !!config.stripeSecretKey && !!config.stripeWebhookSecret;
-}
+import Stripe from 'stripe';
+import { config } from '../config.js';
+import logger from './logger.js';
+
+let stripe = null;
+
+export function getStripe() {
+    if (!stripe && config.stripeSecretKey) {
+        try {
+            stripe = new Stripe(config.stripeSecretKey, {
+                apiVersion: '2026-09-30.endive',
+            });
+        } catch (err) {
+            logger.warn({ err }, 'Failed to initialize Stripe client');
+        }
+    }
+    if (!stripe && config.stripeSecretKey) {
+        logger.warn('getStripe() returned null but STRIPE_SECRET_KEY is configured');
+    }
+    return stripe;
+}
+
+/**
+ * Billing is enabled only when BOTH halves of the Stripe pair are present.
+ *
+ * The secret key alone is enough to open a checkout and charge a card, but
+ * without the webhook signing secret every event Stripe sends back is refused
+ * (stripe-webhooks.js answers 503), so no licence is issued and no e-mail is
+ * sent: the customer pays and receives nothing. In production the boot audit
+ * already refuses to start in that state (startup-secrets-check.js), which is
+ * why this never reached the live instance — but a self-hosted or staging
+ * instance running outside production had no such guard, and this module
+ * disagreed with the shell, which has always required both before advertising
+ * a priced plan (index.js). One predicate, one answer: a half-configured
+ * install advertises Free and answers 503 on checkout, which is the truth.
+ */
+export function isStripeEnabled() {
+    return !!config.stripeSecretKey && !!config.stripeWebhookSecret;
+}
diff --git "a/server/routes/stripe-webhooks.js" "b/server/routes/stripe-webhooks.js"
--- "a/server/routes/stripe-webhooks.js"
+++ "b/server/routes/stripe-webhooks.js"
@@ -1,533 +1,534 @@
-import { getStripe, isStripeEnabled } from '../lib/stripe.js';
-import { config } from '../config.js';
-import db from '../db.js';
-import logger from '../lib/logger.js';
-import { issueLicenseForCheckout } from '../lib/license-issuer.js';
-
-const VALID_TIERS = new Set(['free', 'pro', 'enterprise']);
-
-// A refund or chargeback suspends access, but the Stripe subscription itself
-// is untouched and keeps producing `customer.subscription.updated` events with
-// status 'active'. Letting those through would silently restore the tier of a
-// customer who took their money back, so the hold survives until it is cleared
-// deliberately — `charge.dispute.closed` with status 'won', or an operator.
-const HOLD_STATUSES = new Set(['refunded', 'disputed']);
-
-/**
- * Cross-check the tier from session/subscription metadata against the actual
- * price object's metadata. If they disagree, log a warning and prefer the
- * price's tier (it's the source of truth — session metadata can be stale or
- * tampered if the Stripe account is compromised). Falls back to the supplied
- * `metadataTier` if we can't fetch the price (e.g. line items missing).
- */
-async function reconcileTierFromPrice(stripe, sessionOrSub, metadataTier, sessionId) {
-    try {
-        let priceTier = null;
-        if (sessionId) {
-            const items = await stripe.checkout.sessions.listLineItems(sessionId, { expand: ['data.price'], limit: 5 });
-            priceTier = items.data?.[0]?.price?.metadata?.tier || null;
-        } else if (sessionOrSub?.items?.data?.[0]?.price?.metadata?.tier) {
-            priceTier = sessionOrSub.items.data[0].price.metadata.tier;
-        }
-        if (priceTier && VALID_TIERS.has(priceTier)) {
-            if (metadataTier && metadataTier !== priceTier) {
-                logger.warn({ priceTier, metadataTier }, 'Stripe webhook: tier mismatch between session metadata and price metadata; using price metadata');
-            }
-            return priceTier;
-        }
-    } catch (err) {
-        logger.warn({ err }, 'Stripe webhook: failed to reconcile tier from price; using metadata fallback');
-    }
-    return VALID_TIERS.has(metadataTier) ? metadataTier : 'pro';
-}
-
-/**
- * Read both shapes Stripe has sent since 2025-03-31.basil, once, at the door.
- *
- * The endpoint pins no API version, so events render at the account default.
- * From basil onward `current_period_start/end` left the Subscription object
- * for its items, and the invoice→subscription pointer moved from
- * `invoice.subscription` to `invoice.parent.subscription_details.subscription`.
- * Every handler below reads the older names; on a basil-default account a
- * first purchase still works (it reads only session.*) while renewals,
- * dunning and delayed-payment completions silently no-op and
- * `customer.subscription.updated` throws on `new Date(undefined)`. Filling
- * the older names from the newer ones here is smaller and safer than
- * touching a dozen call sites, and it does nothing on a pre-basil payload.
- */
-export function normaliseStripeEventShape(event) {
-    const obj = event?.data?.object;
-    if (!obj || typeof obj !== 'object') return event;
-    if (obj.object === 'invoice' && !obj.subscription) {
-        const viaParent = obj.parent?.subscription_details?.subscription;
-        if (viaParent) obj.subscription = typeof viaParent === 'string' ? viaParent : viaParent.id;
-    }
-    if (obj.object === 'subscription') {
-        const item = obj.items?.data?.[0];
-        if (obj.current_period_start == null && item?.current_period_start != null) obj.current_period_start = item.current_period_start;
-        if (obj.current_period_end == null && item?.current_period_end != null) obj.current_period_end = item.current_period_end;
-    }
-    return event;
-}
-
-export async function stripeWebhookHandler(req, res) {
-    if (!isStripeEnabled() || !config.stripeWebhookSecret) {
-        return res.status(503).json({ error: 'Stripe webhooks not configured' });
-    }
-
-    const stripe = getStripe();
-    const sig = req.headers['stripe-signature'];
-
-    let event;
-    try {
-        event = stripe.webhooks.constructEvent(req.body, sig, config.stripeWebhookSecret);
-    } catch (err) {
-        logger.error({ err }, 'Stripe webhook signature verification failed');
-        return res.status(400).json({ error: 'Invalid signature' });
-    }
-    normaliseStripeEventShape(event);
-
-    // Idempotency: Stripe retries up to 5 times. Use INSERT OR IGNORE so the
-    // check-then-insert is one atomic statement (no race window between two
-    // concurrent retries). `changes` reports 0 when the event id was already
-    // present, in which case we reply 200 and skip further processing.
-    //
-    // Important: we wrap the idempotency insert + synchronous DB mutations
-    // for this event in a single better-sqlite3 transaction. If any of those
-    // synchronous writes throws, SQLite rolls back the idempotency row so a
-    // Stripe retry will reprocess the event fresh rather than see it as
-    // already-handled. Async side effects (Stripe API calls, license
-    // issuance + email) are performed OUTSIDE the transaction — their order
-    // is: idempotency INSERT + DB writes (inside txn) → email (after commit).
-    // If the async license issuance throws, we remove the idempotency row
-    // explicitly so the next retry can proceed.
-    let deduped = false;
-    const runIdempotentDbWork = db.transaction(() => {
-        const result = db.prepare(
-            'INSERT OR IGNORE INTO webhook_events (id, source, type, processed_at) VALUES (?, ?, ?, ?)'
-        ).run(event.id, 'stripe', event.type, Date.now());
-        if (result.changes === 0) {
-            deduped = true;
-            return null;
-        }
-        // Only the sync DB writes that depend on the event body run here. The
-        // per-event-type async handling (Stripe API calls, license emission)
-        // runs outside, after commit. We return a structured "pending" record
-        // the caller uses to drive the async phase.
-        return { kind: 'committed' };
-    });
-
-    let ledgerResult;
-    try {
-        ledgerResult = runIdempotentDbWork();
-    } catch (err) {
-        logger.error({ err, eventId: event.id }, 'Stripe webhook: idempotency ledger transaction failed');
-        return res.status(500).json({ error: 'Webhook ledger failure' });
-    }
-
-    if (deduped || ledgerResult === null) {
-        return res.json({ received: true, deduped: true });
-    }
-
-    // Helper: remove the idempotency row when async processing fails, so the
-    // next Stripe retry reprocesses the event rather than being deduped.
-    const forgetIdempotency = () => {
-        try {
-            db.prepare('DELETE FROM webhook_events WHERE id = ? AND source = ?').run(event.id, 'stripe');
-        } catch (cleanupErr) {
-            logger.error({ err: cleanupErr, eventId: event.id }, 'Stripe webhook: failed to roll back idempotency row after async failure');
-        }
-    };
-
-    try {
-        switch (event.type) {
-            case 'checkout.session.completed': {
-                const session = event.data.object;
-                const userId = parseInt(session.metadata?.userId);
-                const rawTier = session.metadata?.tier || 'pro';
-                const tier = await reconcileTierFromPrice(stripe, session, rawTier, session.id);
-                // billingPeriod comes from the checkout session metadata
-                // (routes/billing.js ~line 89); default 'monthly' covers older
-                // clients/webhooks that predate the yearly toggle. The emailed
-                // license's validity must match what was actually paid for — a
-                // monthly $19 sub must not carry a 12-month irrevocable key.
-                const billingPeriod = session.metadata?.billingPeriod === 'yearly' ? 'yearly' : 'monthly';
-                const licenseMonths = billingPeriod === 'yearly' ? 12 : 1;
-
-                // A completed session is not a settled payment. Delayed
-                // payment methods complete the session with payment_status
-                // 'unpaid' and settle (or fail) later. Granting here emailed a
-                // 1-12 month offline-verifiable license BEFORE the money
-                // arrived: if the invoice then failed, `past_due` removed SaaS
-                // access while the emailed key kept working. Park the row as
-                // 'incomplete' instead and let invoice.paid promote it.
-                // Stripe's enum is paid | unpaid | no_payment_required. Match
-                // the one bad value explicitly rather than allowlisting the
-                // good ones, so a session that omits the field entirely keeps
-                // its previous behaviour instead of silently never granting.
-                const paymentPending = session.payment_status === 'unpaid';
-
-                if (userId && paymentPending) {
-                    db.prepare(`
-                        INSERT INTO user_subscriptions (user_id, tier, stripe_customer_id, stripe_subscription_id, status, billing_period)
-                        VALUES (?, 'free', ?, ?, 'incomplete', ?)
-                        ON CONFLICT(user_id) DO UPDATE SET
-                            stripe_customer_id = ?, stripe_subscription_id = ?, status = 'incomplete', billing_period = ?, updated_at = datetime('now')
-                    `).run(userId, session.customer, session.subscription, billingPeriod, session.customer, session.subscription, billingPeriod);
-                    logger.info(
-                        { userId, sessionId: session.id, paymentStatus: session.payment_status },
-                        'stripe-webhook: checkout completed but payment not settled — deferring tier grant and license to invoice.paid'
-                    );
-                    break;
-                }
-
-                if (userId) {
-                    // Synchronous subscription write wrapped in a transaction so
-                    // a failure here rolls back cleanly before we attempt license
-                    // issuance. We run it via db.transaction purely for atomicity
-                    // of the upsert itself — the parent idempotency insert is
-                    // already committed at this point because better-sqlite3
-                    // cannot span async boundaries within a single transaction.
-                    try {
-                        db.transaction(() => {
-                            db.prepare(`
-                                INSERT INTO user_subscriptions (user_id, tier, stripe_customer_id, stripe_subscription_id, status, billing_period)
-                                VALUES (?, ?, ?, ?, 'active', ?)
-                                ON CONFLICT(user_id) DO UPDATE SET
-                                    tier = ?, stripe_customer_id = ?, stripe_subscription_id = ?, status = 'active', billing_period = ?, updated_at = datetime('now')
-                            `).run(userId, tier, session.customer, session.subscription, billingPeriod, tier, session.customer, session.subscription, billingPeriod);
-                        })();
-                    } catch (err) {
-                        logger.error({ err, sessionId: session.id }, 'stripe-webhook: subscription upsert failed — rolling back idempotency');
-                        forgetIdempotency();
-                        return res.status(500).json({ error: 'Subscription write failed' });
-                    }
-
-                    // Issue + email license AFTER DB commit. If license issuance
-                    // throws, roll back the idempotency row so Stripe's retry
-                    // can reprocess this event fresh and we get another shot at
-                    // emitting the license. The subscription upsert above is
-                    // idempotent (ON CONFLICT DO UPDATE) so re-running it on
-                    // retry is safe — we don't need to undo it.
-                    //
-                    // Note: issueLicenseForCheckout swallows its OWN errors
-                    // (email failures, signing-key issues) and does not throw
-                    // in those cases — so only an unexpected failure such as
-                    // Stripe customer retrieval timing out will land here.
-                    try {
-                        const stripeCustomer = await stripe.customers.retrieve(session.customer);
-                        const user = db.prepare('SELECT email FROM users WHERE id = ?').get(userId);
-                        const recipientEmail = stripeCustomer.email || user?.email;
-                        if (recipientEmail) {
-                            await issueLicenseForCheckout({
-                                userId,
-                                email: recipientEmail,
-                                tier,
-                                seats: parseInt(session.metadata?.seats) || 1,
-                                months: licenseMonths,
-                                stripeSubscriptionId: session.subscription,
-                                stripeSessionId: session.id,
-                            });
-                        } else {
-                            logger.warn({ userId, sessionId: session.id }, 'stripe-webhook: no email for license delivery');
-                        }
-                    } catch (err) {
-                        logger.error({ err, sessionId: session.id }, 'stripe-webhook: license issuance failed — rolling back idempotency so Stripe retry can reprocess');
-                        forgetIdempotency();
-                        return res.status(500).json({ error: 'License issuance failed' });
-                    }
-                }
-                break;
-            }
-
-            case 'customer.subscription.updated': {
-                const sub = event.data.object;
-                const rawSubTier = sub.metadata?.tier || (sub.items?.data?.[0]?.price?.metadata?.tier) || 'pro';
-                const tier = await reconcileTierFromPrice(stripe, sub, rawSubTier, null);
-                const periodStart = new Date(sub.current_period_start * 1000).toISOString();
-                const periodEnd = new Date(sub.current_period_end * 1000).toISOString();
-
-                // Never let a routine subscription update lift a refund/dispute
-                // hold. The customer opening the billing portal is enough to
-                // produce this event, and Stripe reports the subscription as
-                // 'active' throughout — the money is still gone.
-                const current = db.prepare(
-                    'SELECT status FROM user_subscriptions WHERE stripe_subscription_id = ?'
-                ).get(sub.id);
-
-                // 'incomplete' is invoice.paid's only record that a delayed
-                // payment (SEPA, ACH, Boleto) still owes a licence. Stripe does
-                // not order subscription.updated against invoice.paid, so if
-                // this landed first it granted the tier before the money was
-                // confirmed and invoice.paid then found nothing to settle — no
-                // key was ever issued. Periods are safe to record; the tier and
-                // an 'active' status are invoice.paid's to grant. A failure
-                // status (past_due, incomplete_expired, …) still lands.
-                if (current?.status === 'incomplete') {
-                    const promotes = sub.status === 'active' || sub.status === 'trialing';
-                    db.prepare(`
-                        UPDATE user_subscriptions SET
-                            ${promotes ? '' : 'status = ?,'} current_period_start = ?, current_period_end = ?, updated_at = datetime('now')
-                        WHERE stripe_subscription_id = ?
-                    `).run(...(promotes ? [] : [sub.status]), periodStart, periodEnd, sub.id);
-                    break;
-                }
-
-                if (current && HOLD_STATUSES.has(current.status)) {
-                    db.prepare(`
-                        UPDATE user_subscriptions SET
-                            current_period_start = ?, current_period_end = ?, updated_at = datetime('now')
-                        WHERE stripe_subscription_id = ?
-                    `).run(periodStart, periodEnd, sub.id);
-                    logger.warn(
-                        { subscriptionId: sub.id, heldStatus: current.status },
-                        'stripe-webhook: subscription update ignored — billing hold in effect'
-                    );
-                    break;
-                }
-
-                db.prepare(`
-                    UPDATE user_subscriptions SET
-                        tier = ?, status = ?, current_period_start = ?, current_period_end = ?, updated_at = datetime('now')
-                    WHERE stripe_subscription_id = ?
-                `).run(tier, sub.status, periodStart, periodEnd, sub.id);
-                break;
-            }
-
-            case 'customer.subscription.deleted': {
-                const sub = event.data.object;
-                db.prepare(`
-                    UPDATE user_subscriptions SET tier = 'free', status = 'cancelled', updated_at = datetime('now')
-                    WHERE stripe_subscription_id = ?
-                `).run(sub.id);
-                break;
-            }
-
-            // Refunding an invoice does NOT cancel the subscription in Stripe,
-            // so without these two handlers a refunded or charged-back customer
-            // kept status='active' and full paid capability indefinitely.
-            // Both suspend SaaS access immediately; the already-emailed offline
-            // license key remains valid until its own expiry, which is why
-            // license.js mints a `lid` for a future revocation list.
-            case 'charge.refunded':
-            case 'charge.dispute.created': {
-                const object = event.data.object;
-                const chargeId = event.type === 'charge.refunded' ? object.id : object.charge;
-                const nextStatus = event.type === 'charge.refunded' ? 'refunded' : 'disputed';
-
-                // Stripe fires `charge.refunded` for PARTIAL refunds too, with
-                // `refunded: false`. A goodwill credit on an otherwise-paid
-                // invoice must not strip a paying customer of their tier, so
-                // only a full refund suspends access.
-                if (event.type === 'charge.refunded' && object.refunded !== true) {
-                    logger.info(
-                        { chargeId, amount: object.amount, amountRefunded: object.amount_refunded },
-                        'stripe-webhook: partial refund recorded, access unchanged'
-                    );
-                    break;
-                }
-
-                let subscriptionId = null;
-                try {
-                    // Always re-fetch through the SDK client, which is pinned to
-                    // an API version that still carries `charge.invoice`. The
-                    // event payload renders at the ACCOUNT default, and from
-                    // 2025-03-31.basil a charge has no `invoice` field: a full
-                    // refund then found no subscription and left the customer
-                    // on the paid tier.
-                    const charge = await stripe.charges.retrieve(chargeId);
-                    if (charge?.invoice) {
-                        const invoice = typeof charge.invoice === 'string'
-                            ? await stripe.invoices.retrieve(charge.invoice)
-                            : charge.invoice;
-                        subscriptionId = invoice?.subscription || null;
-                    }
-                } catch (err) {
-                    logger.error({ err, chargeId, eventType: event.type }, 'stripe-webhook: could not resolve subscription for refund/dispute');
-                    forgetIdempotency();
-                    return res.status(500).json({ error: 'Refund resolution failed' });
-                }
-
-                if (!subscriptionId) {
-                    // A one-off charge with no subscription — nothing to suspend.
-                    logger.info({ chargeId, eventType: event.type }, 'stripe-webhook: refund/dispute has no subscription');
-                    break;
-                }
-
-                const result = db.prepare(`
-                    UPDATE user_subscriptions SET tier = 'free', status = ?, updated_at = datetime('now')
-                    WHERE stripe_subscription_id = ?
-                `).run(nextStatus, subscriptionId);
-                logger.warn(
-                    { subscriptionId, eventType: event.type, rowsUpdated: result.changes },
-                    'stripe-webhook: subscription downgraded to free after refund/dispute'
-                );
-                break;
-            }
-
-            // The only automatic way out of a hold. A dispute resolved in the
-            // operator's favour means the money stayed, so the tier is restored
-            // from Stripe rather than from our own (deliberately downgraded)
-            // row. A lost dispute leaves the hold exactly where it is.
-            case 'charge.dispute.closed': {
-                const dispute = event.data.object;
-                if (dispute.status !== 'won') {
-                    logger.info({ disputeId: dispute.id, status: dispute.status }, 'stripe-webhook: dispute closed without a win, hold stands');
-                    break;
-                }
-
-                let subscriptionId = null;
-                try {
-                    const charge = await stripe.charges.retrieve(dispute.charge);
-                    if (charge?.invoice) {
-                        const invoice = typeof charge.invoice === 'string'
-                            ? await stripe.invoices.retrieve(charge.invoice)
-                            : charge.invoice;
-                        subscriptionId = invoice?.subscription || null;
-                    }
-                } catch (err) {
-                    logger.error({ err, disputeId: dispute.id }, 'stripe-webhook: could not resolve subscription for won dispute');
-                    forgetIdempotency();
-                    return res.status(500).json({ error: 'Dispute resolution failed' });
-                }
-
-                if (!subscriptionId) break;
-
-                const sub = await stripe.subscriptions.retrieve(subscriptionId);
-                const rawTier = sub.metadata?.tier || sub.items?.data?.[0]?.price?.metadata?.tier || 'pro';
-                const tier = await reconcileTierFromPrice(stripe, sub, rawTier, null);
-                db.prepare(`
-                    UPDATE user_subscriptions SET tier = ?, status = ?, updated_at = datetime('now')
-                    WHERE stripe_subscription_id = ? AND status = 'disputed'
-                `).run(tier, sub.status, subscriptionId);
-                logger.warn({ subscriptionId, tier }, 'stripe-webhook: dispute won, access restored');
-                break;
-            }
-
-            case 'invoice.payment_failed': {
-                const invoice = event.data.object;
-                if (invoice.subscription) {
-                    db.prepare(`
-                        UPDATE user_subscriptions SET status = 'past_due', updated_at = datetime('now')
-                        WHERE stripe_subscription_id = ? AND status NOT IN ('refunded', 'disputed')
-                    `).run(invoice.subscription);
-                }
-                break;
-            }
-
-            case 'invoice.paid': {
-                const invoice = event.data.object;
-                if (invoice.subscription) {
-                    // Read BEFORE the UPDATE: 'incomplete' means the checkout
-                    // handler deferred the grant because the payment had not
-                    // settled, so this invoice is the moment it becomes real.
-                    const deferred = db.prepare(
-                        "SELECT user_id, billing_period FROM user_subscriptions WHERE stripe_subscription_id = ? AND status = 'incomplete'"
-                    ).get(invoice.subscription);
-
-                    // The 'incomplete' marker is this event's ONLY record that a
-                    // licence is still owed. Clearing it before the key is issued
-                    // meant a failed issuance (which 500s so Stripe retries) came
-                    // back to a row that no longer looked deferred — the customer
-                    // had paid by SEPA or Boleto and silently never got a key.
-                    // Status is flipped after issuance for exactly that reason.
-                    if (deferred?.user_id) {
-                        const sub = await stripe.subscriptions.retrieve(invoice.subscription);
-                        const rawTier = sub.metadata?.tier || sub.items?.data?.[0]?.price?.metadata?.tier || 'pro';
-                        const tier = await reconcileTierFromPrice(stripe, sub, rawTier, null);
-
-                        const user = db.prepare('SELECT email FROM users WHERE id = ?').get(deferred.user_id);
-                        const recipientEmail = invoice.customer_email || user?.email;
-                        if (recipientEmail) {
-                            await issueLicenseForCheckout({
-                                userId: deferred.user_id,
-                                email: recipientEmail,
-                                tier,
-                                seats: 1,
-                                months: deferred.billing_period === 'yearly' ? 12 : 1,
-                                stripeSubscriptionId: invoice.subscription,
-                                stripeSessionId: invoice.id,
-                            });
-                        } else {
-                            logger.warn({ subscriptionId: invoice.subscription, invoiceId: invoice.id }, 'stripe-webhook: no email for deferred license delivery');
-                        }
-
-                        db.prepare(`
-                            UPDATE user_subscriptions SET tier = ?, status = 'active', updated_at = datetime('now')
